  class TreeNode {
    constructor(val) {
      this.val = val; // 节点值
      this.height = undefined; // 节点所在高度
      this.left = null; // 左子树
      this.mid = null; // 中子树
      this.right = null; // 右子树
    }
  }

  class Tree {
    constructor() {
      this.root = null; // 树的根节点
      this.height = 0; // 树的高度
    }

    add(val) {
      const node = new TreeNode(val);

      if (this.root == null) {
        // 如果树是空的，则当前创建的节点将作为根节点
        node.height = 1; // 根节点的高度为1
        this.root = node;
        this.height = 1;
      } else {
        // 如果树不是空的，则从根节点开始比较
        let cur = this.root;

        while (true) {
          // 假设创建的节点node是当前节点cur的子节点，则node节点高度值=cur节点高度值+1
          node.height = cur.height + 1;
          // 如果创建的node进入新层，则更新树的高度
          this.height = Math.max(node.height, this.height);

          if (val < cur.val - 500) {
            // 如果数小于节点的数减去500，则将数插入cur节点的左子树
            if (cur.left == null) {
              // 如果cur节点没有左子树，则node作为cur节点的左子树
              cur.left = node;
              // 停止探索
              break;
            } else {
              // 否则继续探索
              cur = cur.left;
            }
          } else if (val > cur.val + 500) {
            // 如果数大于节点的数加上500，则将数插入节点的右子树
            if (cur.right == null) {
              cur.right = node;
              break;
            } else {
              cur = cur.right;
            }
          } else {
            // 如果数大于节点的数加上500，则将数插入节点的右子树
            if (cur.mid == null) {
              cur.mid = node;
              break;
            } else {
              cur = cur.mid;
            }
          }
        }
      }
    }
  }

  const n = parseInt(await readline());

  const tree = new Tree();

  const nums = (await readline()).split(" ").map(Number);

  for (let i = 0; i < n; i++) {
    tree.add(nums[i]);
  }

  console.log(tree.height);
})();

