#include <stdio.h>
#include <stdlib.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))

typedef struct TreeNode {
    int val; // 节点值
    int height; // 节点所在高度
    struct TreeNode *left; // 左子树
    struct TreeNode *mid; // 中子树
    struct TreeNode *right; // 右子树
} TreeNode;

TreeNode *new_TreeNode(int val) {
    TreeNode *node = (TreeNode *) malloc(sizeof(TreeNode));
    node->val = val;
    node->height = 0;
    node->left = NULL;
    node->mid = NULL;
    node->right = NULL;
    return node;
}

typedef struct Tree {
    TreeNode *root; // 树的根节点
    int height; // 树的高度
} Tree;

Tree *new_Tree() {
    Tree *tree = (Tree *) malloc(sizeof(Tree));
    tree->root = NULL;
    tree->height = 0;
    return tree;
}

void add_Tree(Tree *tree, int val) {
    TreeNode *node = new_TreeNode(val);

    if (tree->root == NULL) {
        // 如果树是空的，则当前创建的节点将作为根节点
        node->height = 1; // 根节点的高度为1
        tree->root = node;
        tree->height = 1;
    } else {
        // 如果树不是空的，则从根节点开始比较
        TreeNode *cur = tree->root;

        while (1) {
            // 假设创建的节点node是当前节点cur的子节点，则node节点高度值=cur节点高度值+1
            node->height = cur->height + 1;
            // 如果创建的node进入新层，则更新树的高度
            tree->height = MAX(node->height, tree->height);

            if (val < cur->val - 500) {
                // 如果数小于节点的数减去500，则将数插入cur节点的左子树
                if (cur->left == NULL) {
                    // 如果cur节点没有左子树，则node作为cur节点的左子树
                    cur->left = node;
                    // 停止探索
                    break;
                } else {
                    // 否则继续探索
                    cur = cur->left;
                }
            } else if (val > cur->val + 500) {
                // 如果数大于节点的数加上500，则将数插入节点的右子树
                if (cur->right == NULL) {
                    cur->right = node;
                    break;
                } else {
                    cur = cur->right;
                }
            } else {
                // 如果数大于节点的数加上500，则将数插入节点的右子树
                if (cur->mid == NULL) {
                    cur->mid = node;
                    break;
                } else {
                    cur = cur->mid;
                }
            }
        }
    }
}

int main() {
    int n;
    scanf("%d", &n);

    Tree *tree = new_Tree();

    for (int i = 0; i < n; i++) {
        int num;
        scanf("%d", &num);

        add_Tree(tree, num);
    }

    printf("%d\n", tree->height);

    return 0;
}
